 if m=='gas_compression':status='PARTIAL independent corroboration — Z=1 ideal branch only';delta='NASA uses total conditions and ideal constant cp; code multiplies by Z and needs consistent state assumptions; real-gas path NOT corroborated.'
 if m=='dryer_chamber':delta='Source supports V/Q residence identity only, not dryer droplet/particle performance or a universal chamber design.'
 if m=='filter_area':delta='Source defines hydraulic loading for media beds; rearrangement to A=Q/loading does not validate cake/filter technology sizing.'
 h=history[m]
