 application.append(dict(method_id=m,physical_principle=row['equipment_category']+'; '+row['equation'],governing_equation=row['equation'],assumptions=assumptions,required_inputs=row['input_quantity']+' '+row['input_unit']+'; '+row['parameter_units'],operating_conditions_and_domain=domain,limitations_and_not_for_use=excluded,additional_process_inputs_or_evidence=missing,required_margins_or_additional_checks=margins,suitability='CONDITIONAL PRELIMINARY SCREENING ONLY; not detailed design',applicability_decision='PARTIAL — documented assumptions; project-specific acceptance not established',source_url=url,unit_contract=unit,numerical_evidence=numerical,original_provenance_link='sizing_source_provenance_register.csv#'+m))
 quantity,models,decision,relationship,gap=P[m]
